fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    
    // If the length is 1, return a clone of the input
    if n == 1 {
        return a.clone();
    }
    
    // Create a new vector for the result
    let mut result = vec![0; n];
    
    // Swap the first and last elements
    result[0] = a[n - 1]; // First element of result is last of input
    result[n - 1] = a[0]; // Last element of result is first of input
    
    // Copy the interior elements
    for i in 1..(n - 1) {
        result[i] = a[i];
    }
    
    result
}